// packages/server/src/services/orphans.ts
async function cancelOrphan(db2, adapter, taskId, engineTaskId) {
  const row = db2.prepare("SELECT status FROM bridge_tasks WHERE id = ?").get(taskId);
  if (row?.status !== "cancelled") return;
  db2.prepare("UPDATE bridge_tasks SET engine_task_id = ? WHERE id = ? AND engine_task_id IS NULL").run(engineTaskId, taskId);
  try {
    await adapter.cancelTask(engineTaskId);
  } catch (err) {
    db2.prepare("UPDATE bridge_tasks SET status = 'queued', last_error = ? WHERE id = ?").run(
      `Cancel failed: ${err?.message || err}`,
      taskId
    );
  }
}

